import { Accessor, batch, createEffect, createMemo, createSelector, createSignal, on, onCleanup } from "solid-js";

import { Audio } from "#core/ui/audio-base/audio-support.js";
import ContextManager from "#core/ui/context-manager/context-manager.js";
import { InputEngineEvent } from "#core/ui/input/input-support.js";
import type { InterfaceModeChangedEventName } from "#core/ui/interface-modes/interface-modes.js";
import NavTray from "#core/ui/navigation-tray/model-navigation-tray.js";
import { TriggerHost, TriggerType } from "#core/ui-next/components/trigger.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { IsHybridActive, IsKeyboardActive, IsMouseActive, IsTouchActive } from "#core/ui-next/services/input.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { createEngineEvent } from "#core/ui-next/utilities/game-core-utilities.js";
import { createWindowEventSignal } from "#core/ui-next/utilities/solid-utilities.js";

import "./tooltip-hidden-hint.jsx";

export const HIDE_TOOLTIPS_HOLD_THRESHOLD_MS = 1000;

export interface TooltipModel extends TriggerHost {
	readonly active: Accessor<string[]>;
	readonly targets: Accessor<Record<string, WeakRef<HTMLElement> | PlotCoord>>;
	readonly locked: Accessor<string | undefined>;
	readonly isAutolockAvailable: Accessor<boolean>;
	readonly childTooltipTable: () => Record<string, Accessor<string[]>>;
	readonly register: (name: string, childListAccessor: Accessor<string[]>) => () => void;
	readonly isActive: (name: string | undefined) => boolean;

	/**
	 * tracks if the user has explicitly hidden tooltips via the inspect action
	 * This is not the same as the tooltip systems being disabled in certain screens
	 */
	readonly tooltipsHidden: () => boolean;

	/** Toggle the tooltipsHidden state. Used by the hold-to-hide inspect action. */
	readonly toggleTooltipsHidden: () => void;

	readonly isLocked: (name: string | undefined) => boolean;
	readonly unlock: () => void;
	readonly pop: () => void;
	readonly getTarget: (name: string) => HTMLElement | PlotCoord | undefined;
	readonly unlockAll: () => void;
	readonly isAutoLocking: (name: string | undefined) => boolean;
	/** Attempt to lock or toggle the lock state of the current active tooltip. */
	readonly lock: () => boolean;

	readonly triggerTooltip: (name: string, type: TriggerType, source: HTMLElement | PlotCoord | undefined) => void;
}

function createTooltipModel(): TooltipModel {
	const [targets, setTargets] = createSignal<Record<string, WeakRef<HTMLElement> | PlotCoord>>({});
	const [active, setActive] = createSignal<string[]>([]);
	const [locked, setLocked] = createSignal<string | undefined>();
	const [tooltipsHidden, setTooltipsHidden] = createSignal<boolean>(false);
	// const [touchPress, setTouchPress] = createSignal<boolean>(false);

	const [childTooltipTable, setChildTooltipTable] = createSignal<Record<string, Accessor<string[]>>>({});
	const [autoLockTooltip, setAutoLockTooltip] = createSignal<string | undefined>();
	let autoLockTimeoutHandle: number | undefined;
	let savedInputContext: InputContext | undefined;
	let inputContextChangedWhileOwned = false;
	const focusManager = FocusManager.get();
	const ignoredInputContextTransitions: { oldContext: InputContext; newContext: InputContext }[] = [];

	const queueIgnoredInputContextTransition = (oldContext: InputContext, newContext: InputContext) => {
		if (oldContext === newContext) {
			return;
		}

		ignoredInputContextTransitions.push({ oldContext, newContext });
	};

	const shouldIgnoreInputContextChange = (contextData: InputContextChangedData) => {
		const ignoredTransitionIndex = ignoredInputContextTransitions.findIndex(
			(transition) =>
				transition.oldContext === contextData.oldContext && transition.newContext === contextData.newContext,
		);

		if (ignoredTransitionIndex < 0) {
			return false;
		}

		ignoredInputContextTransitions.splice(ignoredTransitionIndex, 1);
		return true;
	};

	const claimInputContext = () => {
		if (savedInputContext !== undefined) {
			return;
		}

		ignoredInputContextTransitions.length = 0;
		savedInputContext = Input.getActiveContext();
		inputContextChangedWhileOwned = false;

		if (savedInputContext !== InputContext.Shell) {
			queueIgnoredInputContextTransition(savedInputContext, InputContext.Shell);
			Input.setActiveContext(InputContext.Shell);
		}
	};

	const releaseInputContext = () => {
		if (savedInputContext === undefined) {
			return;
		}

		const contextToRestore = savedInputContext;
		const shouldRestoreInputContext = !inputContextChangedWhileOwned;

		savedInputContext = undefined;
		inputContextChangedWhileOwned = false;

		if (!shouldRestoreInputContext) {
			return;
		}

		const currentContext = Input.getActiveContext();
		if (currentContext !== contextToRestore) {
			queueIgnoredInputContextTransition(currentContext, contextToRestore);
			Input.setActiveContext(contextToRestore);
		}
	};

	const onInputContextChanged = (contextData: InputContextChangedData) => {
		if (shouldIgnoreInputContextChange(contextData)) {
			return;
		}

		if (savedInputContext !== undefined) {
			inputContextChangedWhileOwned = true;
		}
	};

	engine.on("InputContextChanged", onInputContextChanged);

	onCleanup(() => {
		engine.off("InputContextChanged", onInputContextChanged);
		releaseInputContext();
	});

	createEffect(
		on(
			locked,
			(currentLocked, previousLocked) => {
				if (previousLocked === undefined && currentLocked !== undefined) {
					claimInputContext();
				} else if (previousLocked !== undefined && currentLocked === undefined) {
					releaseInputContext();
				}
			},
			{ defer: true },
		),
	);

	const contextManagerChanged = createEngineEvent("OnContextManagerChanged");
	// we do not want to actually import interface-modes here because it would result in ViewManager being imported inside the shell
	const interfaceModeChanged = createWindowEventSignal(
		"interface-mode-changed" as typeof InterfaceModeChangedEventName,
	);
	createEffect(
		on(
			[contextManagerChanged, interfaceModeChanged],
			() => {
				unlockAll();
			},
			{ defer: true },
		),
	);

	const isAutolockAvailable = createMemo(() => {
		return (
			Configuration.getUser().tooltipAutolockEnabled &&
			UI.isMouseAvailable() &&
			!IsTouchActive() &&
			(IsMouseActive() || IsHybridActive())
		);
	});

	const startAutoLock = (tooltipName: string, durationMs: number) => {
		stopAutoLock();
		setAutoLockTooltip(tooltipName);

		autoLockTimeoutHandle = setTimeout(() => {
			const currentTooltipName = autoLockTooltip();
			if (!currentTooltipName) {
				stopAutoLock();
				return;
			}

			const currentActive = active();
			const topActive = currentActive.length > 0 ? currentActive[currentActive.length - 1] : undefined;
			const isAutolockInputActive = IsMouseActive() || IsHybridActive();

			if (
				!isAutolockInputActive ||
				IsTouchActive() ||
				topActive !== currentTooltipName ||
				locked() === currentTooltipName ||
				tooltipsHidden()
			) {
				stopAutoLock();
				return;
			}

			const childTooltipListAccesor = childTooltipTable()[currentTooltipName];
			if (!childTooltipListAccesor || childTooltipListAccesor().length <= 0) {
				stopAutoLock();
				return;
			}

			setLocked(currentTooltipName);
			Audio.playSound("data-audio-activate", "tooltip-nested");
			stopAutoLock();
		}, durationMs);
	};

	const tryStartAutoLock = (tooltipName: string) => {
		if (!isAutolockAvailable()) {
			return;
		}

		if (locked() === tooltipName || tooltipsHidden()) {
			return;
		}

		const timeToLockMs = Configuration.getUser().tooltipAutolock;
		if (timeToLockMs <= 0) {
			// lock immediately, technically shouldn't be possible since the min is 100ms
			setLocked(tooltipName);
			Audio.playSound("data-audio-activate", "tooltip-nested");
			return;
		}

		startAutoLock(tooltipName, timeToLockMs);
	};

	const stopAutoLock = () => {
		if (autoLockTimeoutHandle !== undefined) {
			clearTimeout(autoLockTimeoutHandle);
			autoLockTimeoutHandle = undefined;
		}

		setAutoLockTooltip(undefined);
	};

	const getTarget = (name: string): HTMLElement | PlotCoord | undefined => {
		const target = targets()[name];
		if (target instanceof WeakRef) {
			return target.deref();
		} else {
			return target;
		}
	};

	const register = (name: string, childListAccesor: Accessor<string[]>) => {
		setChildTooltipTable((current) => ({
			...current,
			[name]: childListAccesor,
		}));
		return () => unregister(name);
	};

	const unregister = (name: string) => {
		stopAutoLock();
		const activeIdx = active().indexOf(name);
		batch(() => {
			if (name == locked()) {
				setLocked(undefined);
			}

			if (activeIdx !== -1) {
				setActive((current) => current.slice(0, activeIdx));
			}
		});

		setChildTooltipTable((current) => {
			const next: Record<string, Accessor<string[]>> = { ...current };
			delete next[name];
			return next;
		});
	};

	const unlock = () => {
		stopAutoLock();
		const currentActive = active();
		const lockedTooltip = currentActive[currentActive.length - 1];

		if (lockedTooltip === locked()) {
			let nextTooltip = "";
			if (currentActive.length > 1) {
				nextTooltip = currentActive[currentActive.length - 2];
				batch(() => {
					// not an ideal solution, but on kbm it's unlikely that we want to keep the tooltip raised
					// without it, the tooltip would remain raised until another is triggered
					if (IsKeyboardActive() || IsMouseActive()) {
						setActive((current) => current.slice(0, -1));
					}
					setLocked(nextTooltip);
				});
			} else {
				setLocked(undefined);
			}

			// Ensure we maintain focus by returning focus to the tooltip's target
			let nextTarget = getTarget(lockedTooltip);
			if (!nextTarget && nextTooltip) {
				nextTarget = getTarget(nextTooltip);
			}

			if (nextTarget instanceof HTMLElement) {
				focusManager.setFocus(nextTarget);
			} else if (nextTarget == null) {
				console.error(
					`TooltipModel.unlock: Unable to focus tooltip "${lockedTooltip}" because its target is missing.`,
				);
			}
		}
	};

	const pop = () => {
		stopAutoLock();
		const currentActive = active();
		if (currentActive.length === 0) return;

		const topTooltip = currentActive[currentActive.length - 1];

		setActive((current) => current.slice(0, -1));
		setTargets((current) => {
			const next = { ...current };
			delete next[topTooltip];
			return next;
		});

		if (IsTouchActive()) {
			const nextActive = currentActive.slice(0, -1);
			if (nextActive.length > 1) {
				setLocked(nextActive[nextActive.length - 2]);
			} else {
				setLocked(undefined);
			}
		}
	};

	const unlockAll = () => {
		stopAutoLock();
		// restore focus to the first tooltip target if it exists
		const currentActive = active();
		if (currentActive.length > 0) {
			const firstTooltipTarget = getTarget(currentActive[0]);
			if (firstTooltipTarget && firstTooltipTarget instanceof HTMLElement) {
				focusManager.setFocus(firstTooltipTarget);
			}
		}

		batch(() => {
			setActive([]);
			setLocked(undefined);
			setTargets({});
		});
	};

	const lock = (): boolean => {
		stopAutoLock();
		const currentActive = active();

		if (currentActive.length == 1 && tooltipsHidden()) {
			setLocked(undefined);
			return true;
		}

		const currentTarget = currentActive.length > 0 ? getTarget(currentActive[currentActive.length - 1]) : undefined;

		const isCurrentActiveLocked = isLocked(currentActive[currentActive.length - 1]);
		if (isCurrentActiveLocked) {
			// If using 'toggle-tooltip', hide the tool tip if there is only only 1 active.
			if (active().length <= 1) {
				setLocked(undefined);
				if (currentTarget instanceof HTMLElement) {
					focusManager.setFocus(currentTarget);
				}
			} else {
				unlock();
			}

			return true;
		}

		if (currentActive.length > 0 && currentTarget) {
			const currentTooltipName = currentActive[currentActive.length - 1];
			const childListAccessor = childTooltipTable()[currentTooltipName];
			if (!childListAccessor || childListAccessor().length <= 0) {
				return false;
			}
			setLocked(currentTooltipName);
			Audio.playSound("data-audio-activate", "tooltip-nested");
			return true;
		}

		return false;
	};

	const lockedTooltips = createMemo(() => {
		const result = new Set<string>();
		const currentLocked = locked();
		const activeTooltips = active();

		if (currentLocked !== undefined) {
			result.add(currentLocked);
		}

		// All active tooltips except the top one are considered locked
		for (let i = 0; i < activeTooltips.length - 1; i++) {
			result.add(activeTooltips[i]);
		}

		return result;
	});

	const isLocked = createSelector<Set<string>, string>(lockedTooltips, (name, lockedTooltips) => {
		return lockedTooltips.has(name ?? "");
	});

	const isActive = createSelector<string[], string>(active, (name, activeTooltips) => {
		return activeTooltips.includes(name);
	});

	const isAutoLocking = (name: string | undefined): boolean => {
		const autoLockingTooltip = autoLockTooltip();
		return autoLockingTooltip !== undefined && autoLockingTooltip === name;
	};

	const triggerTooltip = (name: string, type: TriggerType, triggerTarget: HTMLElement | PlotCoord | undefined) => {
		// ignore triggers if the tooltip is locked
		if (isLocked(name)) {
			return;
		}

		if (name === autoLockTooltip()) {
			stopAutoLock();
		}

		if (type === TriggerType.Focus || type === TriggerType.Activate) {
			if (!isActive(name)) {
				let shouldNest: boolean;
				let isRaisingSiblingTooltip = false;
				const currentActive = active();
				if (currentActive.length === 0) {
					shouldNest = false;
				} else {
					const currentTop = currentActive[currentActive.length - 1];
					const currentTopList = childTooltipTable()[currentTop]?.() ?? [];

					// top of stack is not locked and we're trying to activate another tooltip at the same level
					if (currentActive.length > 1 && !isLocked(currentTop)) {
						const previousTop = currentActive[currentActive.length - 2];
						const previousTopList = childTooltipTable()[previousTop]?.() ?? [];
						isRaisingSiblingTooltip = previousTopList.includes(name);
					}

					// only nest if...
					// 1. the new tooltip is a child of the current top and the current top is locked (on non-touch devices, on touch, we can nest regardless of lock state)
					// 2. we're raising a sibling tooltip
					shouldNest =
						isRaisingSiblingTooltip ||
						(currentTopList.includes(name) && (isLocked(currentTop) || IsTouchActive()));
				}

				// we only add to nested active tooltips if the top level tooltip is locked (in an inspect state)
				// const shouldNest = tooltipCtx?.parentName === currentActiveTooltip && (active().length > 0 && isLocked(active()[active().length - 1])) || IsTouchActive();
				if (!shouldNest) {
					setActive([name]);
				} else {
					if (isRaisingSiblingTooltip) {
						setActive((current) => [...current.slice(0, -1), name]);
					} else {
						setActive((current) => [...current, name]);
					}
					tryStartAutoLock(name);
				}
			}

			if (IsTouchActive() || type === TriggerType.Activate) {
				if (active().length > 1) {
					const tooltipToLock = type === TriggerType.Activate ? name : active()[active().length - 2];
					const childListAccessor = childTooltipTable()[tooltipToLock];
					if (childListAccessor && childListAccessor().length > 0) {
						setLocked(tooltipToLock);
					}
				}
			}

			if (triggerTarget) {
				setTargets((current) => ({
					...current,
					[name]: triggerTarget instanceof HTMLElement ? new WeakRef(triggerTarget) : triggerTarget,
				}));
			}
		} else if (type === TriggerType.Blur) {
			setTargets((current) => {
				const next = { ...current };
				delete next[name];
				return next;
			});
			setActive((current) => current.filter((n) => n !== name));
		}
	};

	const handleTouchInput = (event: InputEngineEvent) => {
		// fallback handler for hiding tooltips on touch devices
		if (event.detail.status === InputActionStatuses.FINISH && event.detail.name === "touch-tap") {
			if (active().length === 1 && !locked()) {
				pop();
			}
		}
	};

	const toggleTooltipsHidden = () => {
		const currentlyHidden = tooltipsHidden();
		if (!currentlyHidden) {
			// we don't call unlockAll because we want to keep the first tooltip active so the user can re-enable the tooltip again
			if (active().length > 0) {
				setActive([active()[0]]);
				setLocked(undefined);
			}
			// Show a first-time hint popup so the player knows how to re-enable tooltips.
			const userConfig = Configuration.getUser();
			if (!userConfig.hasSeenTooltipHiddenHint) {
				userConfig.setHasSeenTooltipHiddenHint(true);
				UI.commitApplicationOptions();
				userConfig.saveCheckpoint();
				ContextManager.push("tooltip-hidden-hint", { createMouseGuard: true, singleton: true });
			}
		}
		setTooltipsHidden(!currentlyHidden);
	};

	let inspectHoldTimeoutHandle: number | undefined;

	const clearInspectHold = () => {
		if (inspectHoldTimeoutHandle !== undefined) {
			clearTimeout(inspectHoldTimeoutHandle);
			inspectHoldTimeoutHandle = undefined;
		}
	};

	const handleInspectInput = (inputEvent: InputEngineEvent) => {
		const currentActive = active();
		if (currentActive.length === 0) {
			return;
		}

		const { name, status } = inputEvent.detail;
		const isInspectAction = name === "keyboard-inspect-tooltip" || name === "toggle-tooltip";
		if (!isInspectAction) {
			return;
		}

		if (status === InputActionStatuses.START) {
			clearInspectHold();
			// Only allow hold-to-hide on the root tooltip when it's not locked.
			const rootName = currentActive[0];
			if (isLocked(rootName)) {
				return;
			}
			// eslint-disable-next-line solid/reactivity
			inspectHoldTimeoutHandle = window.setTimeout(() => {
				inspectHoldTimeoutHandle = undefined;
				toggleTooltipsHidden();
			}, HIDE_TOOLTIPS_HOLD_THRESHOLD_MS);
		} else if (status === InputActionStatuses.FINISH) {
			clearInspectHold();
		}
	};

	createEffect(() => {
		if (active().length > 0) {
			window.addEventListener("engine-input", handleInspectInput, true);
			onCleanup(() => {
				clearInspectHold();
				window.removeEventListener("engine-input", handleInspectInput, true);
			});
		}
	});

	createEffect(() => {
		if (IsTouchActive()) {
			document.addEventListener("engine-input", handleTouchInput);
			onCleanup(() => {
				document.removeEventListener("engine-input", handleTouchInput);
			});
		}
	});

	// When tooltips are hidden, show a persistent nav tray entry so the player knows how to unhide them.
	createEffect(() => {
		if (tooltipsHidden() && active().length > 0) {
			NavTray.addPersistentEntry("LOC_UI_SHOW_TOOLTIPS", "toggle-tooltip");
			onCleanup(() => {
				NavTray.removePersistentEntry("toggle-tooltip");
			});
		}
	});

	return {
		active,
		targets,
		locked,
		isAutolockAvailable,
		childTooltipTable,
		register,
		unlock,
		pop,
		getTarget,
		unlockAll,
		isAutoLocking,
		lock,
		isActive,
		isLocked,
		tooltipsHidden,
		toggleTooltipsHidden,
		onTrigger: (name, type, triggerTarget) => {
			triggerTooltip(name, type, triggerTarget);
		},
		triggerTooltip,
	};
}

export const TooltipModel = ModelRegistry.register("TooltipModel", ModelLifecycle.Singleton, createTooltipModel);
